await bash("/opt/venv/bin/python - <<'EOF'
import numpy as np
from scipy.signal import find_peaks
t = np.arange(1826)

def acf(x, ml):
    x = x - x.mean(); n=len(x)
    return np.correlate(x,x,'full')[n-1:n+ml]/np.dot(x,x)

def detect(x, prom):
    n = len(x)
    xd = x - np.polyval(np.polyfit(np.arange(n), x, 1), np.arange(n))
    a = acf(xd, n//2)
    peaks, _ = find_peaks(a[3:], prominence=prom)
    if len(peaks)==0:
        return None
    peaks += 3
    return int(peaks[np.argmax(a[peaks])])

for gen, name in [(lambda s: np.random.default_rng(s).normal(0,0.5,1826), 'rng'),
                  (lambda s: np.random.RandomState(s).normal(0,0.5,1826), 'RS')]:
    for seed in range(10):
        y = 0.01*t + 10 + 3*np.sin(2*np.pi*t/365) + 1.5*np.cos(4*np.pi*t/365) + gen(seed)
        print(name, seed, detect(y, 0.2))
EOF")
